import os, pty, select, sys, time, signal
cmd = sys.argv[1:]
keys = os.environ.get('KEYS','q').encode()
pid, fd = pty.fork()
if pid == 0:
    os.environ.setdefault('TERM','xterm-256color')
    os.execv(cmd[0], cmd)
out=b''
time.sleep(float(os.environ.get('DELAY','0.2')))
try: os.write(fd, keys)
except OSError: pass
end=time.time()+float(os.environ.get('TIMEOUT','2'))
status=None
while time.time()<end:
    r,_,_=select.select([fd],[],[],0.05)
    if fd in r:
        try: chunk=os.read(fd,4096)
        except OSError: break
        if not chunk: break
        out += chunk
    try:
        pid2, st=os.waitpid(pid, os.WNOHANG)
        if pid2:
            status=st; break
    except ChildProcessError: break
if status is None:
    try: os.kill(pid, signal.SIGTERM)
    except ProcessLookupError: pass
    try: pid2,status=os.waitpid(pid,0)
    except Exception: status=-1
print('STATUS', status)
print('BYTES', len(out))
s=out[:5000].decode('utf-8','replace')
print(s.encode('unicode_escape').decode())
PY
