func main() {
    if len(os.Args) > 1 && (os.Args[1] == "__complete" || os.Args[1] == "__completeNoDesc") {
        handleHiddenComplete(os.Args[1] == "__completeNoDesc", os.Args[2:])
        return
    }

    // The one real Cobra sub-command exposed by ov is "completion".  It wins over a
    // same-named file, matching the observed command-line interface.
    if idx := indexNonFlag(os.Args[1:], "completion"); idx >= 0 {
        before := append([]string{}, os.Args[1:1+idx]...)
        after := append([]string{}, os.Args[1+idx+1:]...)
        opt, err := parseArgs(append(before, filterCompletionArgsForFlags(after)...), false)
        if err != nil {
            exitErr(err)
        }
        // Global help on the completion command prints the completion command help.
        shell, extras, wantsHelp := parseCompletionTail(after)
        if opt.configExplicit && !opt.help {
            readConfigNotice(opt.config)
        }
        if wantsHelp || shell == "" {
            switch shell {
            case "bash":
