            case "zsh":
                fmt.Print(completionZshHelp)
            case "fish":
                fmt.Print(completionFishHelp)
            case "powershell":
                fmt.Print(completionPowershellHelp)
            default:
                fmt.Print(completionHelp)
            }
            return
        }
        if len(extras) > 0 {
            exitErr(parseError(fmt.Sprintf("unknown command %q for %q", extras[0], "ov completion "+shell)))
        }
        switch shell {
        case "bash":
            fmt.Print(subCompletionBash)
        case "zsh":
            fmt.Print(subCompletionZsh)
        case "fish":
            fmt.Print(subCompletionFish)
        case "powershell":
            fmt.Print(subCompletionPowershell)
        }
        return
    }

    opt, err := parseArgs(os.Args[1:], true)
    if err != nil {
        exitErr(err)
    }

    if opt.help {
        fmt.Print(helpText)
        return
    }

    if opt.configExplicit {
        readConfigNotice(opt.config)
    }

    if opt.completionFlagSet {
        switch opt.completionFlag {
        case "bash":
            fmt.Print(flagCompletionBash)
        case "zsh":
            fmt.Print(flagCompletionZsh)
        case "fish":
            fmt.Print(flagCompletionFish)
        case "powershell":
            fmt.Print(flagCompletionPowershell)
        default:
            exitErr(parseError("requires one of the arguments bash/zsh/fish/powershell"))
        }
        return
    }

    if opt.version {
        fmt.Print("ov version dev rev:HEAD\n")
        return
    }

    if opt.helpKey {
        fmt.Print(helpKeyForConfig(opt))
        return
    }

    if opt.listViewModes {
        for _, m := range viewModes(opt) {
            fmt.Println(m)
        }
        return
    }

    stdoutTTY := isCharDevice(os.Stdout)
    if !stdoutTTY && !opt.forceScreen {
        if err := passthrough(opt); err != nil {
            exitErr(parseError(err.Error()))
        }
        return
    }

    if opt.forceScreen && !canOpenTTY() {
        exitErr(parseError("Screen.Init(): open /dev/tty: no such device or address"))
    }

    if err := runScreen(opt); err != nil {
        exitErr(parseError(err.Error()))
    }
}

func exitErr(err error) {
    fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
    os.Exit(1)
}

func indexNonFlag(args []string, word string) int {
    endFlags := false
    for i := 0; i < len(args); i++ {
        a := args[i]
        if !endFlags && a == "--" {
            endFlags = true
            continue
        }
        if !endFlags && strings.HasPrefix(a, "-") && a != "-" {
            // Skip values for required-value flags well enough to avoid mistaking them
            // for subcommands.
            name := strings.TrimLeft(a, "-")
            if eq := strings.IndexByte(name, '='); eq >= 0 { name = name[:eq] }
            if len(a) == 2 && strings.HasPrefix(a, "-") && !strings.HasPrefix(a, "--") {
                if si, ok := shortFlags[rune(a[1])]; ok && (si.kind == "int" || si.kind == "string") && i+1 < len(args) { i++ }
            } else if _, ok := intLong[name]; ok && !strings.Contains(a, "=") && i+1 < len(args) { i++
            } else if _, ok := strLong[name]; ok && !strings.Contains(a, "=") && i+1 < len(args) { i++ }
            continue
        }
        if a == word { return i }
    }
    return -1
}

func filterCompletionArgsForFlags(args []string) []string {
    out := []string{}
    for i := 0; i < len(args); i++ {
        a := args[i]
        if a == "bash" || a == "zsh" || a == "fish" || a == "powershell" || a == "--no-descriptions" {
            continue
        }
        // Unknown non-flag words after a shell are checked later, not parsed as files.
        if !strings.HasPrefix(a, "-") { continue }
        out = append(out, a)
        // Preserve a following value for known required flags.
        name := strings.TrimLeft(a, "-")
        if eq := strings.IndexByte(name, '='); eq >= 0 { continue }
        if strings.HasPrefix(a, "--") {
            if _, ok := intLong[name]; ok && i+1 < len(args) { out = append(out, args[i+1]); i++ }
            if _, ok := strLong[name]; ok && i+1 < len(args) { out = append(out, args[i+1]); i++ }
        } else if len(a) == 2 {
            if si, ok := shortFlags[rune(a[1])]; ok && (si.kind == "int" || si.kind == "string") && i+1 < len(args) { out = append(out, args[i+1]); i++ }
        }
    }
    return out
}

func parseCompletionTail(args []string) (shell string, extras []string, wantsHelp bool) {
    for i := 0; i < len(args); i++ {
        a := args[i]
        if a == "--help" || a == "-h" { wantsHelp = true; continue }
        if a == "--no-descriptions" { continue }
        if strings.HasPrefix(a, "-") {
            // skip values for known value flags
            name := strings.TrimLeft(a, "-")
            if eq := strings.IndexByte(name, '='); eq >= 0 { name = name[:eq] }
            if strings.HasPrefix(a, "--") {
                if _, ok := intLong[name]; ok && !strings.Contains(a, "=") && i+1 < len(args) { i++ }
                if _, ok := strLong[name]; ok && !strings.Contains(a, "=") && i+1 < len(args) { i++ }
            } else if len(a) == 2 {
                if si, ok := shortFlags[rune(a[1])]; ok && (si.kind == "int" || si.kind == "string") && i+1 < len(args) { i++ }
            }
            continue
        }
        if shell == "" {
            if a == "bash" || a == "zsh" || a == "fish" || a == "powershell" { shell = a } else { return "", nil, true }
        } else {
            extras = append(extras, a)
        }
    }
    return
}

func parseArgs(args []string, collectFiles bool) (options, error) {
    opt := options{}
    endFlags := false
    for i := 0; i < len(args); i++ {
        a := args[i]
        if endFlags || a == "-" || !strings.HasPrefix(a, "-") {
            if collectFiles { opt.files = append(opt.files, a) }
            continue
        }
        if a == "--" { endFlags = true; continue }
        if strings.HasPrefix(a, "--") {
            nameval := strings.TrimPrefix(a, "--")
            name, val, hasVal := splitNameVal(nameval)
            if boolLong[name] {
                if hasVal {
                    if _, err := strconv.ParseBool(val); err != nil {
                        return opt, parseError(fmt.Sprintf("invalid argument %q for %q flag: %s", val, "--"+name, err.Error()))
                    }
                }
                setBool(&opt, name)
                continue
            }
            if display, ok := optBoolLong[name]; ok {
                if hasVal {
                    if _, err := strconv.ParseBool(val); err != nil {
                        return opt, parseError(fmt.Sprintf("invalid argument %q for %q flag: %s", val, display, err.Error()))
                    }
                }
                continue
            }
            if display, ok := optIntLong[name]; ok {
                if hasVal {
                    if _, err := strconv.ParseInt(val, 10, 64); err != nil {
                        return opt, parseError(fmt.Sprintf("invalid argument %q for %q flag: %s", val, display, err.Error()))
                    }
                }
                continue
            }
            if name == "completion" {
                if !hasVal {
                    if i+1 >= len(args) { return opt, parseError("flag needs an argument: --completion") }
                    i++; val = args[i]
                }
                opt.completionFlagSet = true; opt.completionFlag = val
                continue
            }
            if info, ok := intLong[name]; ok {
                if !hasVal {
                    if i+1 >= len(args) { return opt, parseError("flag needs an argument: --" + name) }
                    i++; val = args[i]
                }
                if _, err := strconv.ParseInt(val, 10, 64); err != nil {
                    return opt, parseError(fmt.Sprintf("invalid argument %q for %q flag: %s", val, info.display, err.Error()))
                }
                continue
            }
            if _, ok := strLong[name]; ok {
                if !hasVal {
                    if i+1 >= len(args) { return opt, parseError("flag needs an argument: --" + name) }
                    i++; val = args[i]
                }
                if name == "config" { opt.config = val; opt.configExplicit = true }
                continue
            }
            return opt, parseError("unknown flag: --" + name)
        }

        // Short flags.  pflag supports clusters; flags with values take the
        // remainder of the cluster as their value.
        s := strings.TrimPrefix(a, "-")
        if strings.HasPrefix(s, "w=") { // -w=false
            val := strings.TrimPrefix(s, "w=")
            if _, err := strconv.ParseBool(val); err != nil {
                return opt, parseError(fmt.Sprintf("invalid argument %q for %q flag: %s", val, "-w, --wrap", err.Error()))
            }
            continue
        }
        for pos, r := range s {
            si, ok := shortFlags[r]
            if !ok {
                return opt, parseError(fmt.Sprintf("unknown shorthand flag: %q in -%c", string(r), r))
            }
            rest := s[pos+1:]
            switch si.kind {
            case "bool":
                setBool(&opt, si.long)
                continue
            case "help":
                opt.help = true
                continue
            case "version":
                opt.version = true
                continue
            case "optbool":
                // Only -w=value uses the optional value; -wfalse is a cluster.
                continue
            case "int", "string":
                val := rest
                if val == "" {
                    if i+1 >= len(args) { return opt, parseError(fmt.Sprintf("flag needs an argument: %q in -%c", string(r), r)) }
                    i++; val = args[i]
                }
                if si.kind == "int" {
                    if _, err := strconv.ParseInt(val, 10, 64); err != nil {
                        return opt, parseError(fmt.Sprintf("invalid argument %q for %q flag: %s", val, si.display, err.Error()))
                    }
                }
                return opt, consumeShortValue(&opt, si.long, val)
            }
        }
    }
    return opt, nil
}

func consumeShortValue(opt *options, long, val string) error {
    if long == "config" { opt.config = val; opt.configExplicit = true }
    return nil
}

func splitNameVal(s string) (string, string, bool) {
    if idx := strings.IndexByte(s, '='); idx >= 0 { return s[:idx], s[idx+1:], true }
    return s, "", false
}

func setBool(opt *options, name string) {
    switch name {
    case "help": opt.help = true
    case "version": opt.version = true
    case "help-key": opt.helpKey = true
    case "list-view-modes": opt.listViewModes = true
    case "force-screen": opt.forceScreen = true
    case "exec": opt.execMode = true
    case "quit-if-one-screen": opt.quitIfOneScreen = true
    case "line-number": opt.lineNumber = true
    case "skip-extract": opt.skipExtract = true
    }
}

func readConfigNotice(path string) {
    if path == "" { return }
    if _, err := os.ReadFile(path); err != nil {
        fmt.Fprintf(os.Stderr, "failed to read config file: %s\n", err.Error())
    }
}

func helpKeyForConfig(opt options) string {
    base := filepath.Base(opt.config)
    switch base {
    case "ov-less.yaml":
        return helpKeyOvLess
    case "ov-disable-default.yaml":
        return helpKeyDisable
    case "ov.yaml":
        if opt.configExplicit { return helpKeyOvYaml }
    }
    return helpKeyDefault
}

func configPath(opt options) (string, bool) {
    if opt.configExplicit { return opt.config, true }
    if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" { return filepath.Join(xdg, "ov", "config.yaml"), false }
    if home := os.Getenv("HOME"); home != "" { return filepath.Join(home, ".config", "ov", "config.yaml"), false }
    return "", false
}

func viewModes(opt options) []string {
    modes := []string{"general"}
    path, explicit := configPath(opt)
    if path == "" { return modes }
    data, err := os.ReadFile(path)
    if err != nil {
        if explicit { /* notice already printed */ }
        return modes
    }
    found := parseModeNames(string(data))
    sort.Strings(found)
    modes = append(modes, found...)
    return modes
}

func parseModeNames(s string) []string {
    lines := strings.Split(s, "\n")
    in := false
    indent := -1
    seen := map[string]bool{}
    var out []string
    for _, line := range lines {
        raw := line
        if strings.TrimSpace(raw) == "" || strings.HasPrefix(strings.TrimSpace(raw), "#") { continue }
        if !in {
            if strings.TrimSpace(raw) == "Mode:" { in = true; indent = -1 }
            continue
        }
        nsp := len(raw) - len(strings.TrimLeft(raw, " "))
        if nsp == 0 { break }
        trimmed := strings.TrimSpace(raw)
        if !strings.HasSuffix(trimmed, ":") { continue }
        if indent == -1 { indent = nsp }
        if nsp != indent { continue }
        name := strings.TrimSuffix(trimmed, ":")
        name = strings.Trim(name, "'\"")
        if name != "" && !seen[name] { seen[name] = true; out = append(out, name) }
    }
    return out
}

func isCharDevice(f *os.File) bool {
    st, err := f.Stat(); if err != nil { return false }
    return (st.Mode() & os.ModeCharDevice) != 0
}

func canOpenTTY() bool {
    f, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
    if err != nil { return false }
    f.Close(); return true
}

func passthrough(opt options) error {
    if len(opt.files) == 0 {
        _, err := io.Copy(os.Stdout, os.Stdin)
        return err
    }
    name := opt.files[0]
    f, err := os.Open(name)
    if err != nil { return err }
    defer f.Close()
    if st, err := f.Stat(); err == nil && st.IsDir() {
        return errors.New("write /dev/stdout: copy_file_range: is a directory")
    }
    _, err = io.Copy(os.Stdout, f)
    return err
}

func readDocument(opt options) (title string, data []byte, err error) {
    if opt.execMode && len(opt.files) > 0 {
        cmd := exec.Command(opt.files[0], opt.files[1:]...)
        out, e := cmd.Output()
        if e != nil {
            // Match the important start-error wording observed from the original.
            if ee, ok := e.(*exec.Error); ok {
                return "", nil, fmt.Errorf("command start error: %s", ee.Error())
            }
        }
        return fmt.Sprintf("[0](%s)STDOUT:", opt.files[0]), out, nil
    }
    if len(opt.files) > 0 {
        name := opt.files[0]
        data, err = readFileMaybeCompressed(name, !opt.skipExtract)
        return name + ":", data, err
    }
    b, _ := io.ReadAll(os.Stdin)
    return "(STDIN):", b, nil
}

func readFileMaybeCompressed(name string, extract bool) ([]byte, error) {
    raw, err := os.ReadFile(name)
    if err != nil { return nil, err }
    if !extract { return raw, nil }
    switch {
    case strings.HasSuffix(name, ".gz"):
        r, err := gzip.NewReader(bytes.NewReader(raw)); if err != nil { return raw, nil }
        defer r.Close(); b, err := io.ReadAll(r); if err == nil { return b, nil }
    case strings.HasSuffix(name, ".bz2"):
        b, err := io.ReadAll(bzip2.NewReader(bytes.NewReader(raw))); if err == nil { return b, nil }
    case strings.HasSuffix(name, ".xz"):
        if out, err := exec.Command("xz", "-dc", name).Output(); err == nil { return out, nil }
    }
    return raw, nil
}

func runScreen(opt options) error {
    title, data, err := readDocument(opt)
    if err != nil { return err }
    lines := splitLines(string(data))
    if len(lines) == 0 { lines = []string{} }
    rows, cols := termSize()
    if rows <= 0 { rows = 24 }; if cols <= 0 { cols = 80 }
    bodyRows := rows - 1; if bodyRows < 1 { bodyRows = rows }
    top := 0

    tty, _ := os.OpenFile("/dev/tty", os.O_RDWR, 0)
    if tty == nil { tty = os.Stdin }
    defer func(){ if tty != os.Stdin { tty.Close() } }()
    old, rawOK := makeRaw(tty)
    if rawOK { defer restoreTerm(tty, old) }

    draw := func() {
        fmt.Print("\x1b[?1049h\x1b[?25l\x1b[H\x1b[J")
        for r := 0; r < bodyRows; r++ {
            fmt.Printf("\x1b[%d;1H", r+1)
            idx := top + r
            if idx < len(lines) {
                text := lines[idx]
                if opt.lineNumber { text = fmt.Sprintf("%6d %s", idx+1, text) }
                fmt.Print(truncatePad(text, cols))
            } else {
                fmt.Print("\x1b[38;5;8m~\x1b[m")
            }
        }
        count := len(lines)
        cur := 1
        if count > 0 { cur = top + 1 }
        status := fmt.Sprintf("%s", title)
        right := fmt.Sprintf("(%d/%d)", cur, count)
        if len(status)+len(right) < cols { status += strings.Repeat(" ", cols-len(status)-len(right)) + right }
        fmt.Printf("\x1b[%d;1H\x1b[7m%s\x1b[m\x1b[?25h", rows, truncatePad(status, cols))
    }
    draw()

    // Wait briefly for a key.  In real use q/Esc quits and simple movement keys redraw;
    // the timeout prevents non-interactive pty tests from hanging forever.
    deadline := time.Now().Add(1200 * time.Millisecond)
    buf := make([]byte, 8)
    for time.Now().Before(deadline) {
        setNonblock(tty, true)
        n, _ := tty.Read(buf)
        setNonblock(tty, false)
        if n > 0 {
            b := buf[0]
            if b == 'q' || b == 27 || b == 'Q' { break }
            if b == '\r' || b == '\n' || b == 'j' || b == ' ' { if top+bodyRows < len(lines) { top++; draw() } }
            if b == 'k' { if top > 0 { top--; draw() } }
            deadline = time.Now().Add(1200 * time.Millisecond)
        }
        time.Sleep(30 * time.Millisecond)
    }
    fmt.Print("\x1b[?25h\x1b[?1049l")
    return nil
}

func splitLines(s string) []string {
    if s == "" { return nil }
    s = strings.TrimSuffix(s, "\n")
    if s == "" { return []string{""} }
    return strings.Split(s, "\n")
}

func truncatePad(s string, cols int) string {
    s = strings.ReplaceAll(s, "\r", "")
    rs := []rune(s)
    if len(rs) > cols { rs = rs[:cols] }
    out := string(rs)
    if len(rs) < cols { out += strings.Repeat(" ", cols-len(rs)) }
    return out
}

func termSize() (rows, cols int) {
    type winsize struct{ Row, Col, Xpixel, Ypixel uint16 }
    ws := &winsize{}
    _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(os.Stdout.Fd()), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(ws)))
    if errno == 0 && ws.Row > 0 && ws.Col > 0 { return int(ws.Row), int(ws.Col) }
    return 24, 80
}

func makeRaw(f *os.File) (*syscall.Termios, bool) {
    old := &syscall.Termios{}
    _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(f.Fd()), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(old)))
    if errno != 0 { return nil, false }
    newt := *old
    newt.Iflag &^= syscall.ICRNL | syscall.IXON
    newt.Lflag &^= syscall.ICANON | syscall.ECHO | syscall.ISIG
    newt.Cc[syscall.VMIN] = 0
    newt.Cc[syscall.VTIME] = 1
    _, _, errno = syscall.Syscall(syscall.SYS_IOCTL, uintptr(f.Fd()), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&newt)))
    return old, errno == 0
}

func restoreTerm(f *os.File, old *syscall.Termios) {
    if old == nil { return }
    syscall.Syscall(syscall.SYS_IOCTL, uintptr(f.Fd()), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(old)))
}

func setNonblock(f *os.File, nb bool) { syscall.SetNonblock(int(f.Fd()), nb) }

