func noDesc(lines []string) []string {
    out := make([]string, len(lines))
    for i, l := range lines { if p := strings.IndexByte(l, '\t'); p >= 0 { out[i] = l[:p] } else { out[i] = l } }
    return out
}

func handleHiddenComplete(noDescriptions bool, args []string) {
    directive := 0
    var lines []string
    last := ""
    if len(args) > 0 { last = args[len(args)-1] }
    prev := ""
    if len(args) > 1 { prev = args[len(args)-2] }

    emitVals := func(vals []string, desc []string) {
        directive = 4
        if noDescriptions { lines = vals } else if desc != nil { lines = desc } else { lines = vals }
    }

    if prev == "--completion" || strings.HasPrefix(last, "--completion=") {
        emitVals([]string{"bash", "zsh", "fish", "powershell"}, nil)
    } else if prev == "--converter" || strings.HasPrefix(last, "--converter=") {
        emitVals([]string{"es", "raw", "align"}, []string{"es\tEscape Sequence", "raw\tRaw output of escape sequences", "align\tAlign Column Widths"})
    } else if prev == "--config" || strings.HasPrefix(last, "--config=") {
        lines = []string{"yaml"}; directive = 8
    } else if len(args) >= 1 && args[0] == "completion" && (last == "" || !strings.HasPrefix(last, "-")) {
        vals := []string{"bash", "fish", "powershell", "zsh"}
        desc := []string{"bash\tGenerate the autocompletion script for bash", "fish\tGenerate the autocompletion script for fish", "powershell\tGenerate the autocompletion script for powershell", "zsh\tGenerate the autocompletion script for zsh"}
        if last != "" {
            vals2, desc2 := []string{}, []string{}
            for i, v := range vals { if strings.HasPrefix(v, last) { vals2 = append(vals2, v); desc2 = append(desc2, desc[i]) } }
            vals, desc = vals2, desc2
        }
        emitVals(vals, desc)
    } else if strings.HasPrefix(last, "--") {
        lines = append([]string{}, rootFlagDesc...)
        if len(args) >= 1 && args[0] == "completion" {
            // subcommands use their own help flag line and shell subcommands have no-descriptions.
            tmp := []string{}
            for _, l := range lines { if !strings.HasPrefix(l, "--help\t") { tmp = append(tmp, l) } }
            tmp = append(tmp, "--help\thelp for completion")
            if len(args) >= 2 && (args[1] == "bash" || args[1] == "zsh" || args[1] == "fish" || args[1] == "powershell") {
                tmp[len(tmp)-1] = "--help\thelp for " + args[1]
                tmp = append(tmp, "--no-descriptions\tdisable completion descriptions")
            }
            lines = tmp
        }
        if noDescriptions { lines = noDesc(lines) }
        directive = 4
    }

    for _, l := range lines { fmt.Println(l) }
    fmt.Printf(":%d\n", directive)
    fmt.Fprintf(os.Stderr, "Completion ended with directive: %s\n", directiveName(directive))
}

func directiveName(d int) string {
    switch d {
    case 4: return "ShellCompDirectiveNoFileComp"
    case 8: return "ShellCompDirectiveFilterFileExt"
    default: return "ShellCompDirectiveDefault"
    }
}
